sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float radius;
uniform float angle;
layout(color) uniform half4 backColor;
uniform float backAlpha;
uniform float shine;
uniform float shadow;
uniform float follow;
uniform shader extent;
bool inside(float2 q) {
    return q.x >= 0.0 && q.y >= 0.0 && q.x <= size.x && q.y <= size.y;
}
half4 backOf(float2 q, float light) {
    half4 c = image.eval(q);
    return half4(mix(c.rgb, backColor.rgb * c.a, half(clamp(backAlpha, 0.0, 1.0))) * half(light), c.a);
}
half4 main(float2 p) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float s0 = min(0.0, d.x * size.x) + min(0.0, d.y * size.y);
    float s1 = max(0.0, d.x * size.x) + max(0.0, d.y * size.y);
    if (follow > 0.5) {
        float4 lo = float4(extent.eval(float2(8.0, 2.0)));
        float4 hi = float4(extent.eval(float2(24.0, 2.0)));
        if (lo.b > 0.5 && hi.b > 0.5) {
            float span = max(length(size), 1.0);
            s0 = max(s0, (lo.r + lo.g / 255.0) * 2.0 * span - span);
            s1 = min(s1, (hi.r + hi.g / 255.0) * 2.0 * span - span);
        }
    }
    float r = max(radius, 0.001) * min(size.x, size.y);
    float pi = 3.14159265;
    float fold = s1 - clamp(progress, 0.0, 1.0) * (s1 - s0 + pi * r);
    float s = dot(p, d);
    float2 base = p - s * d;
    if (s <= fold) {
        half4 page = image.eval(p);
        float over = 2.0 * fold + pi * r - s;
        float2 q = base + over * d;
        if (over <= s1 && inside(q)) {
            half4 b = backOf(q, 0.9);
            return b + page * (1.0 - b.a);
        }
        return page;
    }
    if (s < fold + r) {
        float k = clamp((s - fold) / r, 0.0, 1.0);
        float back = fold + r * (pi - asin(k));
        float2 q = base + back * d;
        if (back <= s1 && inside(q)) return backOf(q, 0.7 + 0.3 * k);
        float front = fold + r * asin(k);
        float2 f = base + front * d;
        if (inside(f)) {
            half4 c = image.eval(f);
            half glow = half(clamp(shine, 0.0, 1.0) * pow(1.0 - abs(k * 2.0 - 1.0), 4.0) * 0.5);
            return half4(min(c.rgb * half(1.0 - 0.3 * k) + glow * c.a, half3(c.a)), c.a);
        }
        return half4(0.0);
    }
    float fade = 1.0 - (s - fold - r) / (0.6 * r);
    float under = follow > 0.5 ? float(image.eval(p).a) : 1.0;
    if (fade > 0.0 && inside(p)) return half4(0.0, 0.0, 0.0, half(clamp(shadow, 0.0, 1.0) * fade * 0.5 * under));
    return half4(0.0);
}
